import{_ as l,o as i,c as a,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/schueler/akt-halbj-fehlstunden-1.png",u="/bilder/schueler/akt-halbj-fehlstunden-2.png",h="/bilder/schueler/akt-halbj-allgemein-6.png",z=JSON.parse('{"title":"Fehlzeiten tagesbezogen erfassen und auswerten","description":"","frontmatter":{"title":"Fehlzeiten tagesbezogen erfassen und auswerten","source_pageid":531,"source_revision":5321},"headers":[],"relativePath":"schild3/schueler/fehlzeiten-aktuelles-halbjahr-aktueller-abschnitt.md","filePath":"schild3/schueler/fehlzeiten-aktuelles-halbjahr-aktueller-abschnitt.md"}'),o={name:"schild3/schueler/fehlzeiten-aktuelles-halbjahr-aktueller-abschnitt.md"};function d(g,t,m,c,f,b){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="fehlzeiten-tagesbezogen-erfassen-und-auswerten" tabindex="-1">Fehlzeiten tagesbezogen erfassen und auswerten <a class="header-anchor" href="#fehlzeiten-tagesbezogen-erfassen-und-auswerten" aria-label="Permalink to &quot;Fehlzeiten tagesbezogen erfassen und auswerten&quot;">​</a></h1><p>Erfassen Sie Fehlzeiten mit Datum, Stunden, Fach und Lehrkraft. Prüfen Sie zuvor den für Ihre Schule eingestellten Erfassungsmodus.</p><h2 id="fehlzeiten-tagesbezogen-verwalten" tabindex="-1">Fehlzeiten tagesbezogen verwalten <a class="header-anchor" href="#fehlzeiten-tagesbezogen-verwalten" aria-label="Permalink to &quot;Fehlzeiten tagesbezogen verwalten&quot;">​</a></h2><p>Im Reiter <em>Fehlzeiten</em> können beliebige Fehlzeiten, die Option hier ist <em>&quot;tagesbezogen&quot;</em>, erfasst werden. Die Erfassung erfolgt aufgrund der entsprechenden Daten auch konkreten Stunden, Fächern und Lehrkräften zugeordnet.</p><p><a href="/bilder/schueler/akt-halbj-fehlstunden-1.png"><img src="'+s+'" alt="Anlegen einer Zeile für Fehlzeiten." loading="lazy"></a></p><p><em>Anlegen einer Zeile für Fehlzeiten.</em></p><p>Eine neue Zeile wird über das <strong>+</strong> angelegt und mit dem Haken bestätigt.</p><p>In jeder Zeile werden ein <strong>Datum</strong>, ein <strong>Fach</strong> und eine <strong>Lehrkraft</strong>. Um die konkrete Fehlzeit festzuhalten, wird ein Intervall <strong>Von Stunde</strong> bis <strong>Bis Stunde</strong> angelegt, dann wird eingetragen, wie viele konkrete <strong>Fehlstunden</strong> dieser Eintrag beinhaltet.</p><p>Weiterhin wird erfasst, ob diese Fehlzeit als <strong>Entschuldigt</strong> gilt (<em>&quot;Ja&quot;</em>) oder nicht (<em>&quot;Nein&quot;</em>).</p><h2 id="einstellen-der-fehlzeitenverwaltungsart" tabindex="-1">Einstellen der Fehlzeitenverwaltungsart <a class="header-anchor" href="#einstellen-der-fehlzeitenverwaltungsart" aria-label="Permalink to &quot;Einstellen der Fehlzeitenverwaltungsart&quot;">​</a></h2><p><a href="/bilder/schueler/akt-halbj-fehlstunden-2.png"><img src="'+u+'" alt="Fehlzeitenmodus für die Sekundarstufe I und II getrennt einstellen." loading="lazy"></a></p><p><em>Fehlzeitenmodus für die Sekundarstufe I und II getrennt einstellen.</em></p><p>Wie Fehlzeiten erfasst werden, lässt sich über <em>&quot;Verwaltung&quot;</em> ➜ <em>&quot;Einstellungen&quot;</em> ➜ <em>&quot;Fächer, Noten&quot;</em> im Feld <em>&quot;Eingabemodus&quot;</em> jeweils für die Sekundarstufe I und II getrennt einstellen.</p><p>Jeder der beiden Einträge lässt zwischen folgenden Arten wählen:</p><ul><li><strong>Aus den fachbezogenen Fehlstunden berechnen</strong>: Die Fehlstunden werden in den Leistungsdaten in der Zeile für jedes Fach beziehungsweise jeden Kurs erfasst.</li><li><strong>Aus den tagesbezogenen Fehlzeiten berechnen</strong>: Die Fehlstunden werden im <em>&quot;Akt. Halbjahr&quot;</em> über <em>&quot;Fehlzeiten&quot;</em> erfasst.</li><li><strong>Eingabe der Gesamt-Fehlzeiten</strong>: Die Fehlzeiten werden in ihrer Gesamtheit im <em>&quot;Akt. Halbjahr&quot;</em> in den <em>&quot;Allgemeinen Angaben&quot;</em> direkt eingetragen.</li></ul><p>Die Notenerfassung mit GradeHub und WeNoM ist dem SVWS-Server zugeordnet. Einrichtung und Bedienung sind in der <a href="https://doku.svws-nrw.de/" target="_blank" rel="noreferrer">SVWS-Dokumentation</a> beschrieben; siehe auch <a href="/zeugnisse/noteneingabe.html">Noten mit GradeHub und WeNoM erfassen</a>.</p><h2 id="auswerten-von-fehlzeiten" tabindex="-1">Auswerten von Fehlzeiten <a class="header-anchor" href="#auswerten-von-fehlzeiten" aria-label="Permalink to &quot;Auswerten von Fehlzeiten&quot;">​</a></h2>',17),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Je nach von der jeweiligen Prüfungsordnung vorgesehenem Umgang mit Fehlzeiten kann ein systematischer Umgang mit diesen Feldern empfehlenswert sein.")],-1),e("p",null,[n("In den "),e("em",null,"Allgemeinen Angaben"),n(' lässt sich auch das Feld "'),e("strong",null,"Max.Fehlstd."),n('" mit einem Wert für maximale Fehlstunden befüllen. Überschreiten die '),e("strong",null,"Fehlstunden"),n(" den hier gesetzten Wert, wird er fett gedruckt.")],-1),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,'Relevant kann das systematische Verarbeiten von "Maximalen Gesamtfehlstunden" werden, wenn eine Prüfungsordnung die Versendung von Mahnungen oder Entlassungen für das Überschreiten bestimmter Grenzen bei Personen vorsieht, welche ihre Schulpflicht erfüllt haben. Dies trifft etwa für BKs zu.')],-1),r('<h3 id="der-schulerfilter" tabindex="-1">Der Schülerfilter <a class="header-anchor" href="#der-schulerfilter" aria-label="Permalink to &quot;Der Schülerfilter&quot;">​</a></h3><p><a href="/bilder/schueler/akt-halbj-allgemein-6.png"><img src="'+h+'" alt="Felder im Schülerfilter zu Fehlstunden." loading="lazy"></a></p><p><em>Felder im Schülerfilter zu Fehlstunden.</em></p><p>Mit dem <em>Filter I</em> kann auf die Fehlstunden beziehungsweise die unentschuldigten Fehlstunden gefiltert werden, um die Funde dann entsprechend weiter zu nutzen. Der Filter I erlaubt auch eine Angabe von positiven (&quot;Überschreitung&quot;) oder negativen Werten (&quot;nahe dran&quot;), um auf eine <em>Abweichung vom Grenzwert</em> zu filtern.</p><h3 id="datenquellen-im-reportbaukasten" tabindex="-1">Datenquellen im Reportbaukasten <a class="header-anchor" href="#datenquellen-im-reportbaukasten" aria-label="Permalink to &quot;Datenquellen im Reportbaukasten&quot;">​</a></h3><p>Auf Fehlzeiten kann im Reportbaukasten mit den entsprechenden Datenquellen zugegriffen werden.</p><ul><li><em>SchuelerFehlzeiten</em>: Diese <em>schüler</em>bezogene Datenquelle gibt für den Schüler die im jeweiligen Lernabschnitt angefallenen Fehlzeiten aus. Der Report muss hierzu also ein Element der Datenquelle <em>&quot;Lernabschnitte&quot;</em> enthalten.</li><li><strong>FehlzeitenUebersicht</strong> gibt Fehlzeiten für die ausgewählte Schülergruppe aus. Damit lassen sich zum Beispiel eine Tagesmeldung oder die Fehlzeiten ab Monatsbeginn erstellen.</li></ul><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Fehlzeiten_(Aktuelles_Halbjahr_/_Aktueller_Abschnitt" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5321.</p>',9)])])}const k=l(o,[["render",d]]);export{z as __pageData,k as default};
